function soundInit(){if(!audio){const AC=window.AudioContext||window.webkitAudioContext;if(AC)audio=new AC();}audio?.resume();sound=settings.sound;}
function beep(freq=760,dur=.06,volume=.018){if(!sound||!audio||audio.state!=='running')return;const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur);}
function chargeSound(){if(!sound||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.frequency.setValueAtTime(280,audio.currentTime);o.frequency.exponentialRampToValueAtTime(1400,audio.currentTime+1.9);g.gain.setValueAtTime(.09,audio.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+2);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+1.9);}
function master(){const g=audio.createGain();g.gain.value=1;const comp=audio.createDynamicsCompressor();comp.threshold.value=-10;comp.ratio.value=4;g.connect(comp);comp.connect(audio.destination);return g;}
// Defibrillator discharge: low body thump + electrical crack + short buzz. Loud on purpose.
function shockSound(){if(!sound||!audio||audio.state!=='running')return;const t=audio.currentTime,out=master();
 const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(140,t);o.frequency.exponentialRampToValueAtTime(38,t+.38);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.95,t+.012);g.gain.exponentialRampToValueAtTime(.001,t+.5);o.connect(g);g.connect(out);o.start(t);o.stop(t+.55);
 const len=Math.floor(audio.sampleRate*.28),buf=audio.createBuffer(1,len,audio.sampleRate),d=buf.getChannelData(0);for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/len,3);const n=audio.createBufferSource();n.buffer=buf;const bp=audio.createBiquadFilter();bp.type='bandpass';bp.frequency.value=2200;bp.Q.value=.7;const ng=audio.createGain();ng.gain.value=.9;n.connect(bp);bp.connect(ng);ng.connect(out);n.start(t);
 const z=audio.createOscillator(),zg=audio.createGain();z.type='sawtooth';z.frequency.value=95;zg.gain.setValueAtTime(.32,t);zg.gain.exponentialRampToValueAtTime(.001,t+.16);z.connect(zg);zg.connect(out);z.start(t);z.stop(t+.18);
 if(navigator.vibrate)try{navigator.vibrate(180);}catch{}
 $('stage').classList.remove('shock-flash');void $('stage').offsetWidth;$('stage').classList.add('shock-flash');}
