function noiseBurst(dur=.2,freq=1200,q=.8,vol=.4,type='bandpass',sweepTo=null,delay=0){if(!sound||!audio||audio.state!=='running')return;const t=audio.currentTime+delay,len=Math.floor(audio.sampleRate*dur),buf=audio.createBuffer(1,len,audio.sampleRate),d=buf.getChannelData(0);for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);const n=audio.createBufferSource();n.buffer=buf;const f=audio.createBiquadFilter();f.type=type;f.frequency.setValueAtTime(freq,t);if(sweepTo)f.frequency.exponentialRampToValueAtTime(sweepTo,t+dur);f.Q.value=q;const g=audio.createGain();g.gain.value=vol;n.connect(f);f.connect(g);g.connect(audio.destination);n.start(t);}
function tone(freq,dur,vol=.08,type='sine',delay=0,slideTo=null){if(!sound||!audio||audio.state!=='running')return;const t=audio.currentTime+delay,o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);if(slideTo)o.frequency.exponentialRampToValueAtTime(slideTo,t+dur);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+.01);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+dur+.02);}
const SFX={
 monitor:()=>{tone(1046,.09,.09,'sine');tone(1318,.12,.09,'sine',.12);},
 pads:()=>{noiseBurst(.08,500,1,.35,'lowpass');noiseBurst(.08,500,1,.35,'lowpass',null,.14);},
 cpr:()=>{for(let i=0;i<3;i++)tone(90,.12,.25,'sine',i*.545,55);},
 drug:()=>{noiseBurst(.45,3000,2,.18,'bandpass',900);tone(660,.08,.05,'sine',.48);},
 iv:()=>{tone(300,.08,.15,'triangle',0,600);tone(880,.1,.07,'sine',.1);},
 bvm:()=>{noiseBurst(.35,700,1.2,.25,'bandpass',300);},
 airway:()=>{tone(1200,.04,.12,'square');tone(523,.15,.08,'sine',.15);tone(784,.2,.08,'sine',.32);},
 lab:()=>{tone(1318,.25,.1,'sine');tone(988,.4,.1,'sine',.22);},
 good:()=>{tone(880,.1,.07,'sine');tone(1175,.16,.07,'sine',.09);},
 wrong:()=>{tone(220,.18,.09,'sawtooth',0,180);},
 coin:()=>{tone(988,.07,.07,'square');tone(1319,.18,.07,'square',.07);},
 rosc:()=>{[523,659,784,1046].forEach((f,i)=>tone(f,.28,.12,'triangle',i*.14));tone(1046,.6,.09,'sine',.6);},
 alarm:()=>{tone(880,.2,.1,'square');tone(660,.2,.1,'square',.25);},
 temp:()=>{tone(2093,.06,.06,'sine');tone(2093,.06,.06,'sine',.1);}
};
