function chargedTone(){if(!sound||!audio||audio.state!=='running')return;for(let i=0;i<3;i++)setTimeout(()=>beep(1250,.14,.12),i*220);}
function cycleTone(kind){if(!sound||!audio||audio.state!=='running')return;if(kind==='soon'){for(let i=0;i<2;i++)setTimeout(()=>beep(880,.12,.09),i*180);}else{for(let i=0;i<3;i++)setTimeout(()=>{beep(988,.2,.14);setTimeout(()=>beep(740,.2,.14),210);},i*520);}}
