function renderLabs(s){const box=$('lab-results');if(!box)return;const rows=Object.keys(LAB_TESTS).filter(k=>s.labResults[k]||s.labDue[k]).map(k=>s.labResults[k]?`<p><b>${LAB_TESTS[k].label}</b><br>${LAB_VALUES[s.id][k]}</p>`:`<p class="pending"><b>${LAB_TESTS[k].label}</b> · pending ${fmt(Math.max(0,s.labDue[k]-s.t))}</p>`);const html=rows.join('')||'<p class="muted">No tests sent yet.</p>';if(box.innerHTML!==html)box.innerHTML=html;document.querySelectorAll('#lab-picker input').forEach(i=>{const k=i.value;i.disabled=!!(s.labResults[k]||s.labDue[k]);});}
// Findings automatically update the 5 Hs / 5 Ts review (the learner can still change any entry).
const autoMarked={};
function autoReview(s){const mark=(i,value,why)=>{if(autoMarked[i]===value)return;if(causeReview[i]&&causeReview[i]!=='Not reviewed'&&!autoMarked[i])return;autoMarked[i]=value;causeReview[i]=value;sim.log('cause-auto',`${['Hypovolemia','Hypoxia','Hydrogen ion (acidosis)','Hypo-/hyperkalemia','Hypothermia','Tension pneumothorax','Tamponade, cardiac','Toxins','Thrombosis, pulmonary','Thrombosis, coronary','Hypoglycemia'][i]}: ${value} — ${why}`);const el=document.querySelector(`[data-review="${i}"]`);if(el)el.value=value;};
 if(s.iv&&s.fluidBoluses>0)mark(0,'Less likely','IV access and fluid bolus given');
 if(s.intubated)mark(1,'Less likely','airway secured and ventilated');
 if(s.labResults.abg){const ph=parseFloat((LAB_VALUES[s.id].abg.match(/pH ([\d.]+)/)||[])[1]);mark(2,ph<7.2?'Evidence supports':'Less likely',`blood gas pH ${ph}`);}
 if(s.labResults.elyte||s.labResults.abg){const k=parseFloat((LAB_VALUES[s.id][s.labResults.elyte?'elyte':'abg'].match(/K⁺ ([\d.]+)/)||[])[1]);mark(3,k>=6||k<3?'Evidence supports':'Less likely',`K⁺ ${k} mmol/L`);}
 if(s.labResults.dtx){const g=parseFloat((LAB_VALUES[s.id].dtx.match(/DTX ([\d.]+)/)||[])[1]);mark(10,g<70?'Evidence supports':'Less likely',`DTX ${g} mg/dL`);}
 if(s.tempChecked)mark(4,s.temp<35?'Evidence supports':'Less likely',`temperature ${s.temp.toFixed(1)} °C`);
 if(s.pocusLung)mark(5,s.ptx?'Evidence supports':'Less likely',s.ptx?'absent lung sliding on POCUS':'lung sliding seen on POCUS');
 if(s.pocusCardiac)mark(6,'Less likely','no pericardial effusion on POCUS');
 if(s.patch)mark(7,'Evidence supports','fentanyl patch found');
 if(s.id===4&&(sim.awarded.has('ecg12')||s.labResults.tropt))mark(9,'Evidence supports',sim.awarded.has('ecg12')?'inferior ST elevation on 12-lead':'troponin T elevated');
}
