let nextPulseBeep=0;function pulseOx(now){if(!sim||screen!=='play'||!settings.sound||!sim.s.monitor||!sim.s.pulse||sim.s.paused||sim.s.ended||sim.s.spo2==null)return;if(now<nextPulseBeep)return;nextPulseBeep=now+60000/Math.max(30,sim.s.hr||60);tone(440+(Math.max(70,Math.min(100,sim.s.spo2))-70)*14,.07,.035,'sine');}
