 {const ready=Object.keys(s.labResults).length,pend=Object.keys(s.labDue).length;set('lab-status',!ready&&!pend?'Labs not sent':`Labs ${ready} ready${pend?` · ${pend} pending ${fmt(Math.max(0,Math.min(...Object.values(s.labDue))-s.t))}`:''}`);}if($('lab-results'))renderLabs(s);
 set('shock-count',`Shocks delivered: ${s.shocks}`);set('compression-cue',s.paused?'CPR · PAUSED':s.clear?'HANDS CLEAR':teamMotion(s).compressing?'CPR ACTIVE':s.cpr?'CPR · VENTILATION PAUSE':'CPR · STANDBY');$('compression-cue').classList.toggle('active',!s.paused&&teamMotion(s).compressing);
