 if(s.charged&&!wasCharged)chargedTone();wasCharged=s.charged;{const since=s.t-s.epiLast,arrest=!s.pulse&&!s.ended,tile=$('epi-time').parentElement;set('epi-time',s.epi?fmt(since)+(arrest&&since>=300?' · NOW':arrest&&since>=180?' · DUE':''):'—');tile.classList.toggle('epi-due',!!s.epi&&arrest&&since>=180&&since<300);tile.classList.toggle('epi-over',!!s.epi&&arrest&&since>=300);}set('cpr-status',teamMotion(s).label);set('cpr-rate-label',`${s.cprRate} /min`);set('cpr-depth-label',`${s.cprDepth.toFixed(1)} cm · full recoil`);$('quality-bar').style.width=s.cpr?'78%':'0';
 for(const b of document.querySelectorAll('[data-action="cpr"]'))b.innerHTML=(s.cpr?'Pause CPR':'Start / Resume CPR')+'<small>Minimize interruptions</small>';
